/// Implemented by backends that compute off the CPU (M3.3 provenance).
public protocol FPPV3BackendProvenance: Sendable {
    var fppBackendID: String { get }         // "metal"
    var backendDevice: String { get }        // FPPV3MetalBackend.backendDevice
    var gpuKernelVersion: String { get }
}

#if canImport(Metal)
extension FPPV3MetalBackend: FPPV3BackendProvenance {
    public var fppBackendID: String { "metal" }
}
#endif

