    public var u2Sec: [Double]
}

/// One case of the FPP v3 canary fixture.
public struct FPPV3CanaryCase: Sendable {
    public var name: String
    public var family: String
    public var fold: FPPV2ProdFold
    public var ks, pOrbs, incsRad, aRsArr, eccs, wsRad, u1, u2, companionFluxRatio: [Double]
    public var companionIsHost: Bool
    public var cpuLnL: [Double]                 // stored CPU f64 per-draw lnL
    public var inWindow: [Bool]                 // draw inside its TOI's D1' window (CPU lnL >= run max - 40 nat)
    public var eb: FPPV3CanaryEB?

    public init(
        name: String,
        family: String = "S",
        fold: FPPV2ProdFold,
        ks: [Double],
        pOrbs: [Double],
        incsRad: [Double],
        aRsArr: [Double],
        eccs: [Double],
        wsRad: [Double],
        u1: [Double],
        u2: [Double],
        companionFluxRatio: [Double],
        companionIsHost: Bool,
        cpuLnL: [Double],
        inWindow: [Bool],
        eb: FPPV3CanaryEB? = nil
    ) {
        self.name = name
        self.family = family
        self.fold = fold
        self.ks = ks
        self.pOrbs = pOrbs
        self.incsRad = incsRad
        self.aRsArr = aRsArr
        self.eccs = eccs
        self.wsRad = wsRad
        self.u1 = u1
        self.u2 = u2
        self.companionFluxRatio = companionFluxRatio
        self.companionIsHost = companionIsHost
        self.cpuLnL = cpuLnL
        self.inWindow = inWindow
        self.eb = eb
    }
}

