public enum FPPV3CanaryRule {
    public struct Verdict: Equatable, Sendable {
        public var pass: Bool
        public var nChecked: Int
        public var maxAbs: Double
        public var median: Double
        public var nonFinite: Bool

        public init(pass: Bool, nChecked: Int, maxAbs: Double, median: Double, nonFinite: Bool) {
            self.pass = pass
            self.nChecked = nChecked
            self.maxAbs = maxAbs
            self.median = median
            self.nonFinite = nonFinite
        }
    }

    /// D6 (frozen): every draw inside the window has |dlnL| <= 0.1 nat; the MEDIAN over the in-window draws <= 0.002 nat;
    /// out-of-window draws are report-only; ANY non-finite device lnL (in or out of window) => nonFinite = true and pass = false.
    /// An empty in-window set => pass = false (a canary that checks nothing is a failure).
    public static func evaluate(deviceLnL: [Double], cpuLnL: [Double], inWindow: [Bool]) -> Verdict {
        precondition(deviceLnL.count == cpuLnL.count && deviceLnL.count == inWindow.count, "evaluate: length mismatch")
        let nonFinite = deviceLnL.contains(where: { !$0.isFinite }) || cpuLnL.contains(where: { !$0.isFinite })
        var diffs = [Double]()
        diffs.reserveCapacity(deviceLnL.count)
        for i in 0..<deviceLnL.count {
            if inWindow[i] && deviceLnL[i].isFinite && cpuLnL[i].isFinite {
                diffs.append(abs(deviceLnL[i] - cpuLnL[i]))
            }
        }
        let n = diffs.count
        if nonFinite || n == 0 {
            return Verdict(pass: false, nChecked: n, maxAbs: .nan, median: .nan, nonFinite: nonFinite)
        }
        diffs.sort()
        let maxAbs = diffs[n - 1]
        let median = (n % 2 == 1) ? diffs[n / 2] : (diffs[n / 2 - 1] + diffs[n / 2]) / 2.0
        let pass = maxAbs <= 0.1 && median <= 0.002
        return Verdict(pass: pass, nChecked: n, maxAbs: maxAbs, median: median, nonFinite: nonFinite)
    }
}

