    private static func unhx(_ s: String) -> Double {
        guard let bits = UInt64(s, radix: 16) else {
            fatalError("bad f64 hex: \(s)")
        }
        return Double(bitPattern: bits)
    }

    public func resolveURL() throws -> URL {
        if let fileURL, FileManager.default.fileExists(atPath: fileURL.path) {
            return fileURL
        }
        let thisFile = URL(fileURLWithPath: #filePath)
        let root = thisFile.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        let candidates = [
            fileURL,
            root.appendingPathComponent("Tests/ExoNitFPPV2Tests/Fixtures/fpp_gpu_canary_v1.json"),
            root.appendingPathComponent("Fixtures/fpp_gpu_canary_v1.json"),
            URL(fileURLWithPath: "Tests/ExoNitFPPV2Tests/Fixtures/fpp_gpu_canary_v1.json"),
            URL(fileURLWithPath: "Fixtures/fpp_gpu_canary_v1.json"),
            URL(fileURLWithPath: "~/gpu-worktrees/gpu-cuda-int/crates/exonit-core/tests/fixtures/fpp_gpu_canary_v1.json"),
        ].compactMap { $0 }

        for url in candidates {
            if FileManager.default.fileExists(atPath: url.path) {
                return url
            }
        }
        throw FPPV2FoldError(description: "fpp_gpu_canary_v1.json not found in search paths")
    }

    public func load() throws -> [FPPV3CanaryCase] {
        // An explicit fixture remains useful for tests; a missing explicit path must throw.
        // The default is embedded so an installed release works from any directory.
        let data: Data
        if let fileURL {
            data = try Data(contentsOf: fileURL)
        } else {
            data = Data(Self.embeddedJSON.utf8)
        }
        return try Self.parse(data: data)
    }

    public static func parse(data: Data) throws -> [FPPV3CanaryCase] {
        let file = try JSONDecoder().decode(CanaryJSONFile.self, from: data)
        let rf = file.fold
        let nb = rf.n_bins
        let nodeLevels = rf.node_levels
        let ladderMaxK = rf.ladder_max_k

        var nodeTab = [Double](repeating: 0.0, count: nb * nodeLevels * ladderMaxK)
        var compactIdx = 0
        for b in 0..<nb {
            for l in 0..<nodeLevels {
                let count = 4 << l
                for j in 0..<count {
                    nodeTab[(b * nodeLevels + l) * ladderMaxK + j] = unhx(rf.node_tab_compact[compactIdx])
                    compactIdx += 1
                }
            }
        }

        var cases = [FPPV3CanaryCase]()
        cases.reserveCapacity(file.cases.count)

        for rc in file.cases {
            let eb: FPPV3CanaryEB?
            if rc.family == "EB" {
                guard let flags = rc.eb else {
                    throw FPPV2FoldError(description: "EB canary case missing eb flags: \(rc.name)")
                }
                var ebFluxRatios = [Double]()
                var u1Sec = [Double]()
                var u2Sec = [Double]()
                for draw in rc.draws {
                    guard let fr = draw.eb_fluxratio, let u1s = draw.u1_sec, let u2s = draw.u2_sec else {
                        throw FPPV2FoldError(description: "EB canary draw missing EB fields: \(rc.name)")
                    }
                    ebFluxRatios.append(unhx(fr))
                    u1Sec.append(unhx(u1s))
                    u2Sec.append(unhx(u2s))
                }
                eb = FPPV3CanaryEB(
                    sigmaVeto: unhx(flags.sigma_veto), rejectSec: flags.reject_sec,
                    secConsistent: flags.sec_consistent, kNudgeUpstream: flags.k_nudge_upstream,
                    ebFluxRatios: ebFluxRatios, u1Sec: u1Sec, u2Sec: u2Sec
                )
            } else {
                eb = nil
            }
            var fa = FPPV2FoldArrays()
            fa.n = rf.n
            fa.flux = rc.fold_flux.map(unhx)
            fa.sigma = rc.sigma.map(unhx)
            fa.tmean = rf.tmean.map(unhx)
            fa.varT = rf.var_t.map(unhx)
            fa.tmin = rf.tmin.map(unhx)
            fa.tmax = rf.tmax.map(unhx)
            fa.nodeTab = nodeTab
            fa.ptsOff = rf.pts_off
            fa.ptsT = rf.pts_t.map(unhx)

            let prodFold = FPPV2ProdFold(
                arrays: fa,
                f: rc.f.map(unhx),
                w: unhx(rc.w),
                delta: unhx(rc.delta),
                nb: nb,
                baseChi2: unhx(rc.base_chi2),
                lnnorm: unhx(rc.lnnorm)
            )

            let canaryCase = FPPV3CanaryCase(
                name: rc.name,
                family: rc.family,
                fold: prodFold,
                ks: rc.draws.map { unhx($0.k) },
                pOrbs: rc.draws.map { unhx($0.p_orb) },
                incsRad: rc.draws.map { unhx($0.inc_rad) },
                aRsArr: rc.draws.map { unhx($0.a_rs) },
                eccs: rc.draws.map { unhx($0.ecc) },
                wsRad: rc.draws.map { unhx($0.w_rad) },
                u1: rc.draws.map { unhx($0.u1) },
                u2: rc.draws.map { unhx($0.u2) },
                companionFluxRatio: rc.draws.map { unhx($0.companion_fluxratio) },
                companionIsHost: rc.companion_is_host,
                cpuLnL: rc.draws.map { unhx($0.lnl) },
                inWindow: rc.draws.map { $0.in_window },
                eb: eb
            )
            cases.append(canaryCase)
        }
        return cases
    }
}

public typealias FPPV3CanaryLoader = FPPV3RealCanaryFixture

// MARK: - Metal Canary Runner

#if canImport(Metal)
public enum FPPV3MetalCanary {
    /// Runs every S and EB case through its backend entry point and applies FPPV3CanaryRule.
    /// Throws FPPV3GPUFailure.canaryFailed on a failed verdict, .nonFinite is NOT used here (non-finite => .canaryFailed, rule D6),
    /// and rethrows any FPPV3GPUFailure the backend throws (device errors stay device errors). Prints one summary line per case.
    /// Missing EB inputs, unknown families, or an empty fixture fail closed.
    public static func makeRunner(fixture: any FPPV3CanaryFixture) -> @Sendable (FPPV3MetalBackend) throws -> Void {
        return { backend in
            let cases = try fixture.load()
            var casesRun = 0

            for c in cases {
                let result: FPPV3LnLProdResult
                switch c.family {
                case "EB":
                    guard let eb = c.eb else { throw FPPV3GPUFailure.canaryFailed }
                    result = try backend.batchEBTransitLnLProd(
                        fold: c.fold, sigmaVeto: eb.sigmaVeto, ks: c.ks, ebFluxRatios: eb.ebFluxRatios,
                        pOrbs: c.pOrbs, incsRad: c.incsRad, aRsArr: c.aRsArr, eccs: c.eccs, wsRad: c.wsRad,
                        u1: c.u1, u2: c.u2, companionFluxRatio: c.companionFluxRatio,
                        companionIsHost: c.companionIsHost, rejectSec: eb.rejectSec,
                        secConsistent: eb.secConsistent, kNudgeUpstream: eb.kNudgeUpstream,
                        u1Sec: eb.u1Sec, u2Sec: eb.u2Sec
                    )
                case "S":
                    result = try backend.batchTransitLnLProd(
                        fold: c.fold, ks: c.ks, pOrbs: c.pOrbs, incsRad: c.incsRad,
                        aRsArr: c.aRsArr, eccs: c.eccs, wsRad: c.wsRad,
                        u1: c.u1, u2: c.u2, companionFluxRatio: c.companionFluxRatio,
                        companionIsHost: c.companionIsHost
                    )
                default:
                    throw FPPV3GPUFailure.canaryFailed
                }
                casesRun += 1

                let verdict = FPPV3CanaryRule.evaluate(
                    deviceLnL: result.lnL,
                    cpuLnL: c.cpuLnL,
                    inWindow: c.inWindow
                )

                print("[canary] case=\(c.name) pass=\(verdict.pass) n_checked=\(verdict.nChecked) max_abs=\(verdict.maxAbs) median=\(verdict.median) non_finite=\(verdict.nonFinite)")

                if !verdict.pass {
                    throw FPPV3GPUFailure.canaryFailed
                }
            }

            guard casesRun > 0 else {
                throw FPPV3GPUFailure.canaryFailed
            }
        }
    }

    public static func install(on backend: FPPV3MetalBackend, fixture: any FPPV3CanaryFixture) {
        backend.canary = makeRunner(fixture: fixture)
    }
}
#endif
